import { mkdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import { dirname, relative, sep } from "node:path";
import { assertRealPathInsideRepository } from "./assertRealPathInsideRepository.js";
import { configureSparseCheckout, materializeFullCheckout, } from "./checkout/sparseCheckout.js";
import { runGitCommand } from "./gitCommandRunner.js";
import { pendingProjectDiff } from "./pendingProjectDiff.js";
import { resolvePathInsideRepository, UnsafeRepositoryPathError } from "./repositoryPaths.js";
/**
 * Junk that must never reach a co-author's project. Edits are committed with `git add
 * --all`, so anything the operating system or a stray local compile drops into the clone
 * would otherwise be published into someone's paper.
 *
 * This goes in `.git/info/exclude` rather than `.gitignore`, because `.gitignore` is a
 * tracked file and writing one would itself be a change pushed to Overleaf.
 */
const NEVER_PUBLISH_PATTERNS = [
    "# Written by mcp-server-overleaf. Local only; never pushed to Overleaf.",
    ".DS_Store",
    "Thumbs.db",
    "*.aux",
    "*.fdb_latexmk",
    "*.fls",
    "*.log",
    "*.out",
    "*.synctex.gz",
    "",
].join("\n");
export class DetachedHeadError extends Error {
}
export class BinaryFileError extends Error {
}
/** Enough of a file to catch a NUL byte in any real binary format. */
const BINARY_SNIFF_BYTES = 8192;
/**
 * A single Overleaf project clone.
 *
 * Overleaf's git bridge is not a general git remote: every project has exactly one
 * branch with one linear history, force pushes are refused, and there are no tags or
 * LFS. Everything here stays inside that envelope - fast-forward pulls, rebase onto
 * the remote branch, and ordinary pushes.
 */
export class OverleafGitRepository {
    options;
    constructor(options) {
        this.options = options;
    }
    get repositoryDirectory() {
        return this.options.repositoryDirectory;
    }
    get remoteUrl() {
        return `${this.options.overleafGitBaseUrl}/${this.options.overleafProjectId}`;
    }
    git(args, options = {}) {
        return runGitCommand({
            workingDirectory: this.options.repositoryDirectory,
            args,
            overleafGitToken: this.options.overleafGitToken,
            ...options,
        });
    }
    async directoryExists(path) {
        try {
            const entry = await stat(path);
            return entry.isDirectory();
        }
        catch {
            return false;
        }
    }
    /** Clones the project on first use; afterwards this is a cheap no-op. */
    async ensureCloned() {
        if (await this.directoryExists(`${this.options.repositoryDirectory}/.git`)) {
            await this.git(["remote", "set-url", "origin", this.remoteUrl]);
            await this.writeLocalExcludes();
            await this.configureCheckout();
            return;
        }
        await mkdir(dirname(this.options.repositoryDirectory), { recursive: true });
        await runGitCommand({
            workingDirectory: dirname(this.options.repositoryDirectory),
            args: [
                "clone",
                ...(this.options.checkoutMode === "text-only" ? ["--sparse"] : []),
                this.remoteUrl,
                this.options.repositoryDirectory,
            ],
            overleafGitToken: this.options.overleafGitToken,
            timeoutMs: 300_000,
        });
        await this.git(["config", "user.name", this.options.commitAuthorName]);
        await this.git(["config", "user.email", this.options.commitAuthorEmail]);
        await this.writeLocalExcludes();
        await this.configureCheckout();
    }
    async writeLocalExcludes() {
        const excludePath = `${this.options.repositoryDirectory}/.git/info/exclude`;
        await mkdir(dirname(excludePath), { recursive: true });
        await writeFile(excludePath, NEVER_PUBLISH_PATTERNS, "utf8");
    }
    /** Overleaf hard-codes one branch: `main` for recent clones, `master` for older ones. */
    async getBranchName() {
        const { stdout } = await this.git(["rev-parse", "--abbrev-ref", "HEAD"]);
        const branchName = stdout.trim();
        // Detached HEAD reports the literal "HEAD". Left alone, every later command would
        // compare against a nonexistent `origin/HEAD` and quietly misreport the divergence,
        // which is the number the push decision rests on. Say so instead.
        if (branchName === "HEAD" || branchName === "") {
            throw new DetachedHeadError(`The clone at ${this.options.repositoryDirectory} is not on a branch. ` +
                "Overleaf projects have exactly one branch, so this clone was changed outside this server. " +
                "Delete the directory and let it be cloned again.");
        }
        return branchName;
    }
    async getHeadCommitHash() {
        const { stdout } = await this.git(["rev-parse", "HEAD"]);
        return stdout.trim();
    }
    async fetchRemote() {
        await this.git(["fetch", "origin"], { timeoutMs: 180_000 });
    }
    /** How far the local clone and Overleaf have drifted apart, in commits. */
    async describeRemoteDivergence() {
        const branchName = await this.getBranchName();
        const { stdout } = await this.git(["rev-list", "--left-right", "--count", `origin/${branchName}...HEAD`]);
        const [remoteOnly = "0", localOnly = "0"] = stdout.trim().split(/\s+/);
        return {
            branchName,
            commitsOnlyOnRemote: Number.parseInt(remoteOnly, 10) || 0,
            commitsOnlyOnLocal: Number.parseInt(localOnly, 10) || 0,
        };
    }
    /** Replays local commits on top of whatever collaborators pushed. Aborts cleanly on conflict. */
    async rebaseOntoRemote() {
        const branchName = await this.getBranchName();
        // Never let a user's global autoStash setting move unpublished edits into a stash.
        const result = await this.git(["-c", "rebase.autoStash=false", "rebase", `origin/${branchName}`], {
            tolerateFailure: true,
        });
        const rebaseInProgress = await this.directoryExists(`${this.options.repositoryDirectory}/.git/rebase-merge`);
        const rebaseApplyInProgress = await this.directoryExists(`${this.options.repositoryDirectory}/.git/rebase-apply`);
        if (rebaseInProgress || rebaseApplyInProgress) {
            await this.git(["rebase", "--abort"]);
            return { succeeded: false, conflictReport: `${result.stdout}\n${result.stderr}`.trim() };
        }
        return {
            succeeded: result.exitCode === 0,
            conflictReport: result.exitCode === 0 ? "" : `${result.stdout}\n${result.stderr}`.trim() || "Git rebase failed.",
        };
    }
    async listTrackedFiles() {
        const { stdout } = await this.git(["ls-files", "-z"]);
        return stdout.split("\0").filter(Boolean);
    }
    async listUntrackedFiles() {
        const { stdout } = await this.git(["ls-files", "--others", "--exclude-standard", "-z"]);
        return stdout.split("\0").filter(Boolean);
    }
    async getPendingDiffStatistics() {
        const branchName = await this.getBranchName();
        const { stdout } = await this.git(["diff", "--stat", `origin/${branchName}`, "--"]);
        return stdout.trim();
    }
    async configureCheckout() {
        await configureSparseCheckout((args, options) => this.git(args, options), this.options.checkoutMode ?? "full");
    }
    async materializeAllFiles() {
        await materializeFullCheckout((args, options) => this.git(args, options));
    }
    /**
     * True when Git has this path in the index, whatever the working tree looks like. A
     * sparse checkout leaves skipped files tracked, so this is what separates "hidden by
     * sparse checkout" from "does not exist".
     *
     * `:(literal)` stops a name containing `*` or `[` from being read as a glob, and any
     * output at all means the pathspec matched, which also covers a tracked directory whose
     * files are all skipped.
     */
    async isTrackedInIndex(absolutePath) {
        const gitPath = relative(this.options.repositoryDirectory, absolutePath).split(sep).join("/");
        const { stdout } = await this.git(["ls-files", "-z", "--", `:(literal)${gitPath}`]);
        return stdout.split("\0").some((entry) => entry !== "");
    }
    async materializePathIfNeeded(relativePath) {
        const absolutePath = await this.resolveClientPath(relativePath);
        try {
            await stat(absolutePath);
            return;
        }
        catch (error) {
            if (error.code !== "ENOENT")
                throw error;
        }
        // Absent from the working tree means one of two different things, and expanding for
        // the wrong one is a silent, permanent change to the whole project: expansion is
        // sticky, so a mistyped path or a brand-new file would turn text-only checkout off
        // for good and materialize every figure in the project. Expand only for a file Git is
        // actually tracking, which is the case sparse checkout created.
        if (!(await this.isTrackedInIndex(absolutePath)))
            return;
        // Expansion lets Git restore skipped files without overwriting local edits.
        await this.materializeAllFiles();
    }
    /**
     * The single place a client-supplied path becomes an absolute one. Both halves of the
     * guard run here: path arithmetic first, then the symlink check, which needs the disk.
     */
    async resolveClientPath(relativePath) {
        const absolutePath = resolvePathInsideRepository(this.options.repositoryDirectory, relativePath);
        await assertRealPathInsideRepository(this.options.repositoryDirectory, absolutePath);
        return absolutePath;
    }
    async readTextFile(relativePath) {
        await this.materializePathIfNeeded(relativePath);
        const contents = await readFile(await this.resolveClientPath(relativePath));
        // Figures and PDFs decode to pages of mojibake that would go straight into the
        // model's context and tell it nothing. A NUL byte early on is the usual tell.
        if (contents.subarray(0, BINARY_SNIFF_BYTES).includes(0)) {
            throw new BinaryFileError(`${relativePath} is a binary file, not text, so there is nothing readable to return.`);
        }
        return contents.toString("utf8");
    }
    async writeTextFile(relativePath, content) {
        await this.materializePathIfNeeded(relativePath);
        const absolutePath = await this.resolveClientPath(relativePath);
        await mkdir(dirname(absolutePath), { recursive: true });
        await writeFile(absolutePath, content, "utf8");
    }
    /**
     * Removes a file from the working tree. `stageAllAndCommit` runs `git add --all`, which
     * records the deletion, so nothing else is needed for a push to carry it.
     *
     * Sparse checkout is the reason this materializes first: a tracked file can be absent
     * from disk while still being part of the project, and deleting only what is on disk
     * would silently succeed without removing anything.
     */
    async deleteFile(relativePath) {
        await this.materializePathIfNeeded(relativePath);
        const absolutePath = await this.resolveClientPath(relativePath);
        const entry = await stat(absolutePath);
        if (!entry.isFile()) {
            throw new Error(`${relativePath} is a directory, not a file. Only files can be deleted.`);
        }
        await rm(absolutePath);
    }
    /** Moves or renames a file inside the project. Both ends are contained the same way. */
    async moveFile(fromRelativePath, toRelativePath) {
        await this.materializePathIfNeeded(fromRelativePath);
        const fromAbsolutePath = await this.resolveClientPath(fromRelativePath);
        const entry = await stat(fromAbsolutePath);
        if (!entry.isFile()) {
            throw new Error(`${fromRelativePath} is a directory, not a file. Only files can be moved.`);
        }
        // resolveClientPath contains a path that does not exist yet by checking its nearest
        // existing ancestor, so a symlinked directory cannot be used to move a file out.
        const toAbsolutePath = await this.resolveClientPath(toRelativePath);
        await mkdir(dirname(toAbsolutePath), { recursive: true });
        await rename(fromAbsolutePath, toAbsolutePath);
    }
    async fileExists(relativePath) {
        try {
            await this.materializePathIfNeeded(relativePath);
            const entry = await stat(await this.resolveClientPath(relativePath));
            return entry.isFile();
        }
        catch (error) {
            if (error instanceof UnsafeRepositoryPathError || error.code === "ENOENT")
                return false;
            throw error;
        }
    }
    async getWorkingTreeStatus() {
        const { stdout } = await this.git(["status", "--porcelain"]);
        return stdout
            .split("\n")
            .map((line) => line.trimEnd())
            .filter((line) => line !== "");
    }
    async getPendingDiff() {
        const branchName = await this.getBranchName();
        return pendingProjectDiff((args, options) => this.git(args, options), `origin/${branchName}`, (path) => this.resolveClientPath(path));
    }
    async getRemoteCommitHash() {
        const branchName = await this.getBranchName();
        const { stdout } = await this.git(["rev-parse", `origin/${branchName}`]);
        return stdout.trim();
    }
    async getDiffBetweenCommits(fromCommit, toCommit) {
        const { stdout } = await this.git(["diff", `${fromCommit}..${toCommit}`, "--"]);
        return stdout;
    }
    async stageAllAndCommit(commitMessage) {
        await this.git(["add", "--all"]);
        const stagedChanges = await this.git(["diff", "--cached", "--name-only"]);
        if (stagedChanges.stdout.trim() === "") {
            return { committed: false, commitHash: await this.getHeadCommitHash() };
        }
        await this.git(["commit", "-m", commitMessage]);
        return { committed: true, commitHash: await this.getHeadCommitHash() };
    }
    /**
     * Returns the clone to what Overleaf currently holds, dropping unpushed commits as well
     * as uncommitted edits.
     *
     * Resetting to HEAD would not be enough. A refused push leaves its commit behind, so the
     * clone sits ahead of and behind Overleaf at once, and a later rebase conflicts on the
     * same lines forever. That is a dead end with no way out but deleting the directory.
     */
    async discardAllLocalChanges() {
        await this.fetchRemote();
        const { commitsOnlyOnLocal } = await this.describeRemoteDivergence();
        const branchName = await this.getBranchName();
        await this.git(["reset", "--hard", `origin/${branchName}`]);
        await this.git(["clean", "-fd"]);
        return { discardedCommits: commitsOnlyOnLocal };
    }
    async pushToOverleaf() {
        const branchName = await this.getBranchName();
        const result = await this.git(["push", "origin", `${branchName}:${branchName}`], {
            tolerateFailure: true,
            timeoutMs: 300_000,
        });
        const report = `${result.stdout}\n${result.stderr}`.trim();
        await this.fetchRemote();
        const divergence = await this.describeRemoteDivergence();
        return { succeeded: divergence.commitsOnlyOnLocal === 0, report };
    }
    async getRecentCommitLog(maxEntries) {
        const { stdout } = await this.git([
            "log",
            `--max-count=${maxEntries}`,
            "--date=iso",
            "--pretty=format:%h  %ad  %an  %s",
        ]);
        return stdout;
    }
}
